mapper.select:
SELECT *
FROM model_invocation
WHERE enterprise_id = #{enterpriseId}
  AND user_id = #{userId}
  AND device_id = #{deviceId}
  AND client_instance_id = #{clientInstanceId}
  AND client_request_id = #{clientRequestId}

mapper.insert:
INSERT INTO model_invocation_event (
    invocation_id, event_sequence, event_id, event_type, status,
    status_revision, event_digest, stream_digest, metadata_json, created_at
) VALUES (
    #{invocationId}, #{eventSequence}, #{eventId}, #{eventType}, #{status},
    #{statusRevision}, #{eventDigest}, #{streamDigest}, #{metadataJson}, #{createdAt}
)
ON CONFLICT (invocation_id, event_sequence) DO NOTHING

mapper.select:
SELECT *
FROM model_invocation_event
WHERE invocation_id = #{invocationId}
  AND event_sequence = #{eventSequence}

SELECT *
FROM model_invocation_event
WHERE invocation_id = #{invocationId}
  AND event_sequence > #{afterSequence}
ORDER BY event_sequence
LIMIT #{limit}

mapper.insert:
INSERT INTO model_invocation_recovery_lease (
    invocation_id, owner_node_id, fencing_epoch, status_revision,
    lease_expires_at, database_observed_at, recovery_attempt,
    policy_revision, updated_at
) VALUES (
    #{invocationId}, #{ownerNodeId}, #{fencingEpoch}, #{statusRevision},
    #{leaseExpiresAt}, #{databaseObservedAt}, #{recoveryAttempt},
    #{policyRevision}, #{updatedAt}
)
ON CONFLICT (invocation_id) DO NOTHING

INSERT INTO model_invocation_audit_outbox (
    outbox_id, invocation_id, event_id, event_type, event_digest,
    created_at, published_at, attempt_count
) VALUES (
    #{outboxId}, #{invocationId}, #{eventId}, #{eventType}, #{eventDigest},
    #{createdAt}, #{publishedAt}, #{attemptCount}
)
ON CONFLICT (outbox_id) DO NOTHING

INSERT INTO model_invocation_provider_attempt (
    usage_authority, authority_invocation_id, provider_attempt_key,
    fencing_epoch, registered_at
) VALUES (
    #{usageAuthority}, #{authorityInvocationId}, #{providerAttemptKey},
    #{fencingEpoch}, #{registeredAt}
)
ON CONFLICT (usage_authority, authority_invocation_id, provider_attempt_key)
DO NOTHING

mapper.select:
SELECT *
FROM model_invocation_provider_attempt
WHERE usage_authority = #{usageAuthority}
  AND authority_invocation_id = #{authorityInvocationId}
  AND provider_attempt_key = #{providerAttemptKey}

SELECT *
FROM model_invocation_usage_fact
WHERE usage_authority = #{usageAuthority}
  AND authority_invocation_id = #{authorityInvocationId}
  AND provider_attempt_key = #{providerAttemptKey}

mapper.insert:
INSERT INTO model_invocation_cache_context (
    invocation_id, cache_execution_authority, gateway_contract_version,
    session_scope_digest, cache_context_digest, context_record_digest, created_at
) VALUES (
    #{invocationId}, #{cacheExecutionAuthority}, #{gatewayContractVersion},
    #{sessionScopeDigest}, #{cacheContextDigest}, #{contextRecordDigest}, #{createdAt}
)
ON CONFLICT (invocation_id) DO NOTHING

mapper.select:
SELECT * FROM model_invocation_prompt_cache_plan
WHERE cache_scope_id_digest = #{cacheScopeIdDigest}
  AND static_source_lock_digest = #{staticSourceLockDigest}
  AND binding_revision = #{bindingRevision}
  AND binding_digest = #{bindingDigest}
  AND profile_revision = #{profileRevision}
  AND profile_digest = #{profileDigest}
  AND compatibility_fingerprint_digest = #{compatibilityFingerprintDigest}
  AND cache_policy_revision = #{cachePolicyRevision}
  AND provider_projection_mode = #{providerProjectionMode}
ORDER BY created_at DESC, invocation_id DESC
LIMIT 1
